/* qryComprasTotal_ComTabelaReducao_FiliaisEspecificas */ ; select selecionados9.*,  np.fornecedor,  np.tipofornecedor,  coalesce(vf.nome, vf.razao) as nomefornecedor,   (select estoques_produtoempromocao(selecionados9.produto, 1)) as produtoempromocao,  False as Selecionado from (  select selecionados8.*,   (  select count(*) from  (     (    select ps.codigo as ps_codigo      from (produtos ps   join caracteristicas cs   on ps.caracteristica = cs.codigo),    (    select distinct  psel.codigo as psel_codigo,  psel.caracteristica as psel_caracteristica,  psel.agrupamentosimilares as psel_agrupamentosimilares,  psel.grade1 as psel_grade1,  psel.grade2 as psel_grade2,  psel.valorgrade1 as psel_valorgrade1,  psel.valorgrade2 as psel_valorgrade2,  psel.composto as psel_composto,  s."similar"    from similares s right outer join    (  select p.codigo,   p.caracteristica,   c.agrupamentosimilares,  c.grade1,  c.grade2,  p.valorgrade1,  p.valorgrade2,  c.composto   from produtos p  join caracteristicas c  on p.caracteristica = c.codigo  where p.codigo = selecionados8.produto  ) as psel    on s.caracteristica = psel.caracteristica   ) as psel_similar    where (ps.caracteristica = psel_similar.similar or   ps.caracteristica = psel_similar.psel_caracteristica)    and ps.codigo <> psel_similar.psel_codigo   /*  and ((ps.inativo IS NULL) OR  (ps.inativo>CURRENT_DATE))  */    and case when coalesce(psel_agrupamentosimilares, '') = 'L'  AND psel_grade1 IS NOT NULL  AND psel_valorgrade1 IS NOT NULL then     ps.valorgrade1 = psel_valorgrade1  and cs.grade1 = psel_grade1      when coalesce(psel_agrupamentosimilares, '') = 'C'  AND psel_grade2 IS NOT NULL  AND psel_valorgrade2 IS NOT NULL then     ps.valorgrade2 = psel_valorgrade2  and cs.grade2 = psel_grade2    else true end     limit 1    )   union all    (  SELECT ps."similar" as ps_codigo  FROM produtos_similares ps  WHERE ps.produto = selecionados8.produto limit 1    )    ) as ps    ) <> 0 AS ExisteSimilar  from (  select  (cast(ROUND( ( cast((total_vendido) as float) / periodo) * sugestaopara ) as float) - total_estoque - total_pedido + futuro) as sugestao,  selecionados7.*   from  (   select selecionados6.*,  /*  case when selecionados6.diasestoque_geral > '60' then  '60'  else  */  coalesce((select rcc.sugestaopara  from reducaoconsultacompras rcc  where rcc.estoquepara <= selecionados6.diasestoque_geral  and 'f'  and (select max(rcc2.estoquepara) from reducaoconsultacompras rcc2) >= selecionados6.diasestoque_geral  order by rcc.estoquepara   desc limit 1),'60')  /* end */ as sugestaopara  from  (   select selecionados5.*,    cast(  case when coalesce(total_vendido,0)<>0 then  (emestoque / (total_vendido / periodo ))  else  cast(999999.99 as numeric(11,2))  end as numeric(12,2)) as diasestoque,   cast(  case when coalesce(total_vendido,0)<>0 then  ((total_estoque + case when /*NULL*/ false then 0 else total_pedido end - futuro)/  (total_vendido / periodo ))  else  cast(999999.99 as numeric(11,2))  end as numeric(12,2)) as diasestoquecompedidosdecompra,   case when 'f' /*and not 'f'*/ then    cast(  case when coalesce(vendido_filiais,0)<>0 then  ((estoque_filiais + total_pedido_filiais)/  (vendido_filiais / Periodo))  else  cast(null as numeric(11,2))  end as numeric(12,2))   else   cast(  case when coalesce(total_vendido,0)<>0 then  (emestoque / (total_vendido / periodo ))  else  cast(999999.99 as numeric(11,2))  end as numeric(12,2))  end as diasestoque_geral      from  (  SELECT *,  /*SE TEM SUGESTAO DE COMPRA, DE ACORDO COM DIASESTOQUE, ENTAO RECALCULA A SUGESTAO DE ACORDO COM DIAS PROPORCIONAL*/  case when sugestao1 <= 0 then 0 else (cast(ROUND( ( cast((total_vendido) as float) / periodo) * '60' ) as float) - total_estoque - total_pedido + futuro) end as sugestao2  from  (  SELECT *, (cast(ROUND( ( cast((total_vendido) as float) / periodo) * '60' ) as float) - total_estoque - total_pedido + futuro) AS sugestao1  FROM  (  SELECT selecionados2.*,  colunasprecos.valor AS precovenda,  cast(case when selecionados2.customedio = 0 then 0  else ROUND( (colunasprecos.valor / selecionados2.customedio - 1) * 100,2)  end as numeric(15,2)) AS markup,   case when selecionados2.datacadastro between '22/01/2026' and '21/07/2026' then  case when '21/07/2026' = selecionados2.datacadastro then 1  else '21/07/2026' - selecionados2.datacadastro end  else '180' end as periodo   FROM  (  select selecionados1.*,  estoques.precoCOMicms, estoques.precoSEMicms, estoques.aliquotaIPI,  estoques.qtdecompra,  estoques.datacompra,  cast(case when (quantidadetotaldoestoque(estoques.produto,estoques.filial)) = 0 then 0  else ROUND( estoques.financeiro /  (quantidadetotaldoestoque(estoques.produto,estoques.filial)),2)  end as numeric(11,2)) AS customedio  FROM   (                                 select p.*,  cast(case when (p.minimo - p.saldo)<0 then 0 else (p.minimo-p.saldo) end as float) as sugestaominimo,  cast(case when (p.maximo - p.saldo)<0 then 0 else (p.maximo-p.saldo) end as float) as sugestaomaximo    from  (  select p.*,  ( p.total_pedidos_fornecedores + p.total_pedidos_filiais) AS total_pedido,   p.total_estoque + p.total_pedidos_fornecedores - p.futuro as saldo   from  (   select p.linha,  p.coluna,  p.codigogrupo,  p.grupo,  p.codigomarca,  p.marca,  p.codigoclasse,  p.classe,  p.promocao,  p.descricaopromocao,  p.produto,  p.produtovisual,  p.nomeproduto,  p.valorgrade1,  p.valorgrade2,  p.csosn,  p.incidencia,  p.composto,  p.caracteristica,  p.caracteristicavisual,  p.referencia,  p.resultadocurvaabc,  p.lembrarpedido,   p.obslembrarpedido,   p.datacadastro,  p.preco,    coalesce((select e2.filial  from estoques e2  where e2.produto = p.produto and  e2.datacompra = max(e.datacompra)  limit 1), 1) as filial,    sum(0 + e.emEstoque + e.Reservado + e.Transito + e.Demonstracao + e.Conserto + e.Danificada + e.reservaprevia) as total_estoque,    SUM ( e.emestoque ) AS emEstoque,  SUM ( e.transito ) AS total_transito,   /* SUM ( estoquesprodutos.pedido + estoquesprodutos.pedidos_filiais) AS total_pedido,*/   /* SUM ( estoquesprodutos.pedido) AS total_pedidos_fornecedores, pedidos_estoquepedido_filial */ /* SUM ( estoquesprodutos.pedidos_filiais) as total_pedidos_filiais, pedidos_filial */ /* SUM ( estoquesprodutos.vendido ) AS total_vendido, vendido_filial */    CAST (SUM (e.reservado) as float) as reservado,  CAST (SUM (e.reservaprevia) as float) as reservaprevia,  CAST (SUM (e.futuro) as float) as futuro,  cast(SUM(e.minimo) as float) as minimo,   cast (SUM (maximo) as float) as maximo,     case when not 'f' then sum(p.vendido_filiais)   else   coalesce(sum((SELECT sum(quantidade)  from json_to_recordset(movimentos_vendido_json) as (filial integer, quantidade numeric(11,3))  where json_to_recordset.filial = e.filial  )),0)+  coalesce(sum((SELECT sum(quantidade)  from json_to_recordset(cast(faturadosnaoentregues_ as json)) as (filial integer, quantidade numeric(11,3))  where json_to_recordset.filial = e.filial  )),0)  end as total_vendido, /* vendido */   /*  case when not 'f' then  sum(p.pedidos_filiais)  else  */   coalesce(sum((SELECT sum(quantidade)  from json_to_recordset(pedidos_filiais_json) as  (requisitante integer, quantidade numeric(11,3))  where json_to_recordset.requisitante = e.filial  )),0)   /*end */ as total_pedidos_filiais, /* pedidos_filiais */   case when not 'f' then sum(p.pedidos_estoquepedido_filiais)  else  coalesce(sum((SELECT sum(quantidade)  from json_to_recordset(pedidos_estoquepedido_json) as (filialentrega integer, quantidade numeric(11,3))  where json_to_recordset.filialentrega = e.filial)),0)  end as total_pedidos_fornecedores, /* pedidos_estoquepedido */   sum(p.vendido_filiais) as vendido_filiais,  sum(p.pedidos_filiais) as pedidos_filiais,  sum(p.pedidos_estoquepedido_filiais) as pedidos_estoquepedido_filiais,  sum(( p.pedidos_estoquepedido_filiais + p.pedidos_filiais)) AS total_pedido_filiais,  sum(p.estoque_filiais) as estoque_filiais     from estoques e,      (   select p.*,     coalesce((SELECT sum(quantidade)  from json_to_recordset(movimentos_vendido_json) as (quantidade numeric(11,3))),0)+  coalesce((SELECT sum(quantidade)  from json_to_recordset(cast(faturadosnaoentregues_ as json)) as (quantidade numeric(11,3))),0)   as vendido_filiais,   coalesce((SELECT sum(quantidade)  from json_to_recordset(pedidos_estoquepedido_json) as (quantidade numeric(11,3))),0)  as pedidos_estoquepedido_filiais,   coalesce((SELECT sum(quantidade)  from json_to_recordset(pedidos_filiais_json) as (situacao char(1), quantidade numeric(11,3))  where json_to_recordset.situacao = 'A'  ),0)  as pedidos_filiais        from  (    select p.*,   movimentos_vendido_json('22/01/2026', '21/07/2026', p.produto, p.listafiliais, ''/*NULL*/),    ( select json_agg(sel.jsonr) from   (SELECT json_build_object('filial', filial, 'quantidade', quantidade) as jsonr  from json_to_recordset(cast(faturadosnaoentregues as json)) as (filial integer, quantidade numeric(11,3))  where json_to_recordset.filial in (select * from lista_int(cast('{'||p.listafiliais||'}' as integer[])))  ) as sel) as faturadosnaoentregues_,     case when 'f' then cast(null as json) else  (select jsonr from pedidos_estoquepedido_json (p.produto, p.listafiliais))  end as pedidos_estoquepedido_json,     case when not 't' then cast(null as json) ELSE   ( select json_agg(sel.jsonr) from (   select json_build_object('requisitante', pf.requisitante,  'quantidade', sum((case when pf.situacao='A' then pf.qtdepedida else pf.qtderecebida end)),  'situacao', pf.situacao) as jsonr  from pedidosfiliais pf  where pf.produto = p.produto  and pf.requisitante in (select * from lista_int(cast('{'||p.listafiliais||'}' as integer[])))  and pf.situacao in ('A','F')  group by pf.requisitante, pf.situacao) as sel  )   end as pedidos_filiais_json   FROM (   select p.*,  cast(e.filial as varchar) as ListaFiliais, /* cast(e.filial as varchar) as ListaFiliais, */  sum(0 + e.emEstoque + e.Reservado + e.Transito + e.Demonstracao + e.Conserto + e.Danificada + e.reservaprevia) as estoque_filiais /* sum(0 + e.emEstoque + e.Transito) as estoque_filiais */ from estoques e,   (  select p.*,   cast(faturadosnaoentregues.jsonr as varchar(1000)) as faturadosnaoentregues from (  select  gr1.descricao as linha  , gr2.descricao as coluna  , c.grupo as codigogrupo  , g.descricao as grupo  , c.marca as codigomarca  , m.descricao as marca  , c.classe as codigoclasse  , cl.descricao as classe  , p.promocao  , pro.descricao as descricaopromocao  , p.codigo as produto  , p.codigovisual as produtovisual  , p.descricao as nomeproduto  , p.valorgrade1  , p.valorgrade2  , c.composto  , p.caracteristica  , c.codigovisual as caracteristicavisual  , p.referencia  , p.preco  , p.resultadocurvaabc  , p.lembrarpedido  , p.obslembrarpedido  , p.datacadastro  , (  select  ti.valor  from  tributosicms ti  where  ti.codigo = c.incidencia  )  as incidencia  , c.csosn  from  ((((((caracteristicas c  join  marcas m  on  c.marca = m.codigo)  join  grupos g  on  c.grupo = g.codigo)  join  classes cl  on  c.classe = cl.codigo)  join  (produtos p  left join  promocoes pro  on  p.promocao = pro.codigo)  on  p.caracteristica = c.codigo)  left join  grades gr1  on  gr1.codigo = c.grade1)  left join  grades gr2  on  gr2.codigo = c.grade2)  where  p.caracteristica = c.codigo  and c.marca = m.codigo  and c.grupo = g.codigo  and c.classe = cl.codigo    and (g.codigo = '130' )                   ) as p   left join /* Questão de perforamance foi feito a consulta abaixo e não produto por produto como as demais */    (   select *   from ProdutosContratosFaturadosouParciaisNaoEntregues_setof('22/01/2026', '21/07/2026', '')  ) as faturadosnaoentregues  on p.produto = faturadosnaoentregues.produto   ) as p   where e.produto = p.produto   /*  Ficou sem sentido restringir a seleção da filial (filial da data de compra) na qual vai ser totalizada geral ao usar tabela redutora  */   /*  and case when not 'f' or ('f' and 'f') then  e.filial =      coalesce((select e2.filial  from estoques e2  where e2.produto = e.produto           order by e2.datacompra desc limit 1    ), 1)    else true end   */   and ( e.filial IN ('1'))          group by p.produto,   e.filial,  p.datacadastro,   p.linha,  p.coluna,  p.codigogrupo,  p.grupo,  p.codigomarca,  p.marca,  p.codigoclasse,  p.classe,  p.promocao,  p.descricaopromocao,  p.produto,  p.produtovisual,  p.nomeproduto,  p.valorgrade1,  p.valorgrade2,  p.composto,  p.caracteristica,  p.caracteristicavisual,  p.referencia,  p.preco,  p.resultadocurvaabc,  p.lembrarpedido,  p.obslembrarpedido,  p.datacadastro,  p.incidencia,  p.csosn,  p.faturadosnaoentregues       ) as p ) as p  ) as p   where p.produto = e.produto  and case when 'f' then  e.filial in ((select * from lista_int(cast('{'||p.ListaFiliais||'}' as integer[]))))  else  e.filial = cast(p.ListaFiliais as integer)  end    and ( e.filial IN ('1'))       group by    p.linha,  p.coluna,  p.codigogrupo,  p.grupo,  p.codigomarca,  p.marca,  p.codigoclasse,  p.classe,  p.promocao,  p.descricaopromocao,  p.produto,  p.produtovisual,  p.nomeproduto,  p.valorgrade1,  p.valorgrade2,  p.csosn,  p.incidencia,  p.composto,  p.caracteristica,  p.caracteristicavisual,  p.referencia,  p.resultadocurvaabc,  p.lembrarpedido,   p.obslembrarpedido,   p.datacadastro,  p.preco   ) as p   ) as p                                       ) AS selecionados1 join estoques on selecionados1.produto = estoques.produto and  selecionados1.filial = estoques.filial  ) as selecionados2, filiais, colunasprecos  where selecionados2.filial = filiais.codigo and  colunasprecos.caracteristica = selecionados2.caracteristica and  colunasprecos.preco = selecionados2.preco and  colunasprecos.coluna = filiais.preconormal  ) AS selecionados3          ) as selecionados4  ) as selecionados5   /* sugestao2 */      ) as selecionados6  ) as selecionados7 ) as selecionados8   /* sugestao8 */    ) as selecionados9   left join notaspag np on( np.codigo = (select max(pn.codigonota)  from produtosnotaspag pn,notaspag np1  where pn.produto = selecionados9.produto  and np1.codigo=pn.codigonota  and np1.tipofornecedor<>'L'  and ehnotafiscalentradacompra(pn.codigofiscal))  ) left join vfornecedores vf on (np.fornecedor = vf.codigo and np.tipofornecedor = vf.tipo)     ORDER BY UPPER(TO_ASCII(nomeproduto,'LATIN1')), produto, valorgrade1, valorgrade2, codigomarca, UPPER(TO_ASCII(marca,'LATIN1')) ;
/* qryComprasGruposFiliais */  ;  select selecionados.*,   /* case when sugestao1 <= 0 then 0  else */ (cast(ROUND( ( cast((total_vendido) as float) / periodo) * sugestaopara ) as float) - total_estoque - total_pedido + futuro)   /* end */ as sugestao    from  (   select selecionados.*,   coalesce((select rcc.sugestaopara  from reducaoconsultacompras rcc  where rcc.estoquepara <= selecionados.diasestoque_geral  and 'f'  and (select max(rcc2.estoquepara) from reducaoconsultacompras rcc2) >= selecionados.diasestoque_geral  order by rcc.estoquepara desc limit 1),'60')  as sugestaopara   from  (     select selecionados.*,   cast(  case when coalesce(total_vendido,0)<>0 then  ((total_estoque /*emEstoque*/ /*+ case when NULL true then 0 else total_pedido end*/ ) /  (total_vendido / Periodo))  else  cast(999999.99 as numeric(11,2))  end as numeric(12,2)) as diasestoque,     case when 'f' /*and not NULL*/ then    cast(  case when coalesce(vendido_filiais,0)<>0 then  ((estoque_filiais + pedidos_filiais)/  (vendido_filiais / Periodo))  else  cast(null as numeric(11,2))  end as numeric(12,2))   else     cast(  case when coalesce(total_vendido,0)<>0 then  ((total_estoque /*emEstoque*/ /*+ case when NULL true then 0 else total_pedido end*/)/  (total_vendido / Periodo))  else  cast(999999.99 as numeric(11,2))  end as numeric(12,2))     end as diasestoque_geral,     cast(  case when coalesce(total_vendido,0)<>0 then  ((total_estoque + /*case when NULL false then 0 else*/ total_pedido /*end*/ - futuro)/  (total_vendido / Periodo))  else  cast(999999.99 as numeric(11,2))  end as numeric(12,2)) as diasestoquecompedidosdecompra,   cast(0 as integer) as filial   from     (  /*  select     SELECT selecionados.*,   (cast(ROUND( ( cast(total_vendido as float)/ periodo) * '60' ) as float) - total_estoque - total_pedido + futuro) AS sugestao1,   case when NULL <> 0 then cast(total_estoque * 100 / NULL as numeric(6,2)) else 0 end as percEstoque, ???  cast(100 as numeric(6,2)) as PercEstoque     (select max(cast(m.data||' '||m.hora as timestamp))  from movimentos m  where m.produto = selecionados.produto  and m.filial = selecionados.filial  and m.tipomovimento = 'STC') as datahorapedido   FROM  (       */          SELECT       fgf.grupo,  g.mnemonico,  s.produto,  s.periodo,    SUM ( s.total_estoque ) AS total_estoque,  SUM ( s.total_transito ) AS total_transito,  SUM ( s.total_pedidos_fornecedores + s.total_pedidos_filiais) AS total_pedido,  /*SUM ( s.pedido + s.pedidos_filiais) AS total_pedido, */    SUM ( s.total_pedidos_fornecedores) AS total_pedidos_fornecedores, /* total_pedidos_fornecedores, */    SUM ( s.total_pedidos_filiais) AS total_pedidos_filiais, /* total_pedido_filiais*/  /* SUM ( s.pedidos_filiais) AS pedidos_filial, */    SUM ( s.total_vendido ) AS total_vendido, /*total_vendido*/    CAST(SUM (s.reservado) as float) as reservado,  CAST(SUM (s.reservaprevia) as float) as reservaprevia,      CAST(SUM(s.minimo) as float) as minimo,   CAST(case when SUM(s.minimo - s.saldo)<0 then 0 else SUM(s.minimo-s.saldo) end as float) as sugestaominimo,  CAST(SUM (s.maximo) as float) as maximo,   CAST(case when SUM(s.maximo - s.saldo)<0 then 0 ELSE sum(s.maximo-s.saldo) end as float) as sugestaomaximo,   cast(sum(s.futuro) as float) as futuro,    cast(100 as numeric(6,2)) as PercEstoque,  sum(s.vendido_filiais) as vendido_filiais,  sum(s.estoque_filiais) as estoque_filiais,  sum(s.pedidos_filiais) as pedidos_filiais         from    (   select e.*,     case when e.datacadastro between '22/01/2026' and '21/07/2026' then  case when '21/07/2026' = e.datacadastro then 1  else '21/07/2026' - e.datacadastro end  else '180' end as periodo,    e.total_estoque + e.total_pedidos_fornecedores - e.futuro as saldo    FROM    (     select p.*  , e.filial  , e.datacompra  , 0 + e.emEstoque + e.Reservado + e.Transito + e.Demonstracao + e.Conserto + e.Danificada + e.reservaprevia as total_estoque  , e.emestoque  , e.futuro  , e.transito as total_transito  , e.reservado  , e.reservaprevia  , e.ultimavenda  , coalesce(e.minimo,0) as minimo  , coalesce(e.maximo,0) as maximo,    case when not 'f' then vendido_filiais   else   coalesce((SELECT sum(quantidade)  from json_to_recordset(movimentos_vendido_json) as (filial integer, quantidade numeric(11,3))  where json_to_recordset.filial = e.filial  ),0)+  coalesce((SELECT sum(quantidade)  from json_to_recordset(cast(faturadosnaoentregues_ as json)) as (filial integer, quantidade numeric(11,3))  where json_to_recordset.filial = e.filial  ),0)  end as total_vendido, /* vendido */    case when not 'f' then pedidos_filiais  else  coalesce((SELECT sum(quantidade)  from json_to_recordset(pedidos_filiais_json) as  (requisitante integer, quantidade numeric(11,3))  where json_to_recordset.requisitante = e.filial  ),0)  end as total_pedidos_filiais, /* pedidos_filiais */   case when not 'f' then pedidos_estoquepedido_filiais  else  coalesce((SELECT sum(quantidade)  from json_to_recordset(pedidos_estoquepedido_json) as (filialentrega integer, quantidade numeric(11,3))  where json_to_recordset.filialentrega = e.filial),0)  end as total_pedidos_fornecedores /* pedidos_estoquepedido */          from estoques e,      (  select p.*,      coalesce((SELECT sum(quantidade)  from json_to_recordset(movimentos_vendido_json) as (quantidade numeric(11,3))),0)+  coalesce((SELECT sum(quantidade)  from json_to_recordset(cast(faturadosnaoentregues_ as json)) as (quantidade numeric(11,3))),0)   as vendido_filiais,    coalesce((SELECT sum(quantidade)  from json_to_recordset(pedidos_estoquepedido_json) as (quantidade numeric(11,3))),0)  as pedidos_estoquepedido_filiais,   coalesce((SELECT sum(quantidade)  from json_to_recordset(pedidos_filiais_json) as (quantidade numeric(11,3))),0)  as pedidos_filiais        from  (          select p.*,     movimentos_vendido_json('22/01/2026','21/07/2026', p.produto, p.listafiliais, ''),   ( select json_agg(sel.jsonr) from   (SELECT json_build_object('filial', filial, 'quantidade', quantidade) as jsonr  from json_to_recordset(cast( faturadosnaoentregues.jsonr as json)) as (filial integer, quantidade numeric(11,3))  where json_to_recordset.filial in (select * from lista_int(cast('{'||p.listafiliais||'}' as integer[])))  ) as sel) as faturadosnaoentregues_,    case when 'f' then cast(null as json) else  (select jsonr from pedidos_estoquepedido_json (p.produto, p.listafiliais))  end as pedidos_estoquepedido_json,      case when not 't' then cast(null as json) ELSE    ( select json_agg(sel.jsonr) from (    select json_build_object('requisitante', pf.requisitante, 'quantidade', sum(pf.qtdepedida)) as jsonr   from pedidosfiliais pf  where pf.produto = p.produto  and pf.requisitante in (select * from lista_int(cast('{'||p.listafiliais||'}' as integer[])))  and pf.situacao = 'A'  group by pf.requisitante ) as sel  )     end as pedidos_filiais_json      from  (   select  p.codigo as produto  , p.datacadastro  , cast(e.filial as varchar) as ListaFiliais   , sum(0 + e.emEstoque + e.Reservado + e.Transito + e.Demonstracao + e.Conserto + e.Danificada + e.reservaprevia) as estoque_filiais     from  produtos p join estoques e on p.codigo = e.produto    where    p.codigo in (348056, 329004, 329005, 329002, 192019, 192010, 348060, 348064, 348065, 348066, 2013, 401029, 319144, 319143, 860574, 860441, 860440, 999016, 860198500, 130207, 165011, 860622900, 860623100, 30349, 860340400, 330000, 330045, 319139, 192024, 401033, 130237, 130204, 130200, 432045, 860431, 429017, 166137, 432055, 432056, 183521, 183468, 183531, 183467, 183469, 183470, 1693, 1696, 130246, 192004, 445039, 192018, 192013, 192007, 192015, 192012, 192017, 183326, 183329, 183327, 183328, 444003, 444004, 444001, 444002, 444005, 444007, 444000, 444006, 192001, 183333, 183331, 183332, 860334300, 183335, 183334, 445015, 264019, 264020, 445041, 445043, 445042, 166122, 445064, 445063, 409010, 417117, 409011, 320117, 320279, 164187, 432059, 432060, 417182, 183236, 183435, 165378, 680116, 183201, 164001, 8