ecionados.filial  and m.tipomovimento = 'STC') as datahorapedido   FROM  (             SELECT s.*,  fgf.grupo,  filiais.mnemonico,  filiais.tipofilial,  ( s.total_pedidos_fornecedores + s.total_pedidos_filiais) AS total_pedido, /*total_pedido,*/  case when (s.minimo - s.saldo)<0 then 0 else (s.minimo-s.saldo) end as sugestaominimo,  case when (s.maximo - s.saldo)<0 then 0 else (s.maximo-s.saldo) end as sugestaomaximo  from    (   select e.*,     case when e.datacadastro between '22/01/2026' and '21/07/2026' then  case when '21/07/2026' = e.datacadastro then 1  else '21/07/2026' - e.datacadastro end  else '180' end as periodo,    e.total_estoque + e.total_pedidos_fornecedores - e.futuro as saldo    FROM    (     select p.*  , e.filial  , e.datacompra  , 0 + e.emEstoque + e.Reservado + e.Transito + e.Demonstracao + e.Conserto + e.Danificada + e.reservaprevia as total_estoque  , e.emestoque  , e.futuro  , e.transito as total_transito  , e.reservado  , e.reservaprevia  , e.ultimavenda  , coalesce(e.minimo,0) as minimo  , coalesce(e.maximo,0) as maximo,    case when not 'f' then vendido_filiais   else   coalesce((SELECT sum(quantidade)  from json_to_recordset(movimentos_vendido_json) as (filial integer, quantidade numeric(11,3))  where json_to_recordset.filial = e.filial  ),0)+  coalesce((SELECT sum(quantidade)  from json_to_recordset(cast(faturadosnaoentregues_ as json)) as (filial integer, quantidade numeric(11,3))  where json_to_recordset.filial = e.filial  ),0)  end as total_vendido, /* vendido */    case when not 'f' then pedidos_filiais  else  coalesce((SELECT sum(quantidade)  from json_to_recordset(pedidos_filiais_json) as  (requisitante integer, quantidade numeric(11,3))  where json_to_recordset.requisitante = e.filial  ),0)  end as total_pedidos_filiais, /* pedidos_filiais */   case when not 'f' then pedidos_estoquepedido_filiais  else  coalesce((SELECT sum(quantidade)  from json_to_recordset(pedidos_estoquepedido_json) as (filialentrega integer, quantidade nume