0350, 165720, 166077, 210155, 166084, 165320, 452004, 330046, 401019, 182009, 730053, 730051, 730000, 730240, 730242, 30372, 165583, 165585, 165624, 165589, 165584, 30316, 30191, 30194, 432048, 432049, 165739, 165541, 165740, 240103, 2710005, 330042, 183184, 183186, 183187, 860176, 165736, 330027, 860488300, 182015, 182006, 860340300, 165744, 165741, 165745, 700036, 860622800, 700063, 860623200, 860334100, 187096, 187097, 187098, 187074, 187078, 187094, 680155)  order by p.codigo   )  as p  on  m.produto = p.codigo  , (notaspag np  join produtosnotaspag pnp  left join produtosdadosfiscais pdf   on pnp.dadofiscal = pdf.dadofiscal  and pnp.produto = pdf.produto  and pnp.numeroprodutotabela = pdf.numero  on np.codigo = pnp.codigonota)    , vfornecedores fc  WHERE m.data between '22/01/2026' and '21/07/2026'  AND np.codigo =m.codigonota  AND np.fornecedor =fc.codigo  AND np.tipofornecedor=fc.tipo  and coalesce(m.composto,m.produto) = pnp.produto  and m.filial = pnp.filial  AND CASE when ''='' THEN true ELSE (select true=true) END  and substr(m.operacao,13,1) ='-'  order by  m.produto  , m.data desc      )   ) as sel  GROUP BY  sel.grupo, sel.produto, sel.data, sel.contrato   order by  sel.grupo,  sel.produto,  sel.data desc   ) as selecao1   ) as selecao1 group by grupo, produto, mes order by grupo, produto, mes desc ;
/* qryDetalhesPrecos */  SELECT  e.produto, e.filial,   (CASE WHEN (COALESCE(fpf.fator,0) > 0) then ROUND((cpn.valor * fpf.fator),2)  ELSE cpn.valor END) as valornormal,   COALESCE(cpn.alteracao,cpn.data) as alteracaopreconormal,    (CASE WHEN (COALESCE(fpf.fator,0) > 0) then ROUND((cpp.valor * fpf.fator),2)  ELSE cpp.valor END) as valorpromocao,   case when cpn.validade >= cpp.validade then cpn.validade else cpp.validade end as validade,   p.datacadastro,   (SELECT pr.descricao FROM precos pr WHERE pr.caracteristica = p.caracteristica AND pr.codigo = p.preco) AS descricaopreco,  e.ultimavenda /* fgf.grupo */   FROM estoques e join (produtos p  join caracteristicas c  on p.caracteristica = c.codigo)   on e.produto = p.codigo  /*  join (produtos p left join promocoes pro on p.promocao = pro.codigo)  join caracteristicas c  join marcas m  on c.marca = m.codigo   join grupos g  on c.grupo = g.codigo   join classes cl  on c.classe = cl.codigo   on p.caracteristica = c.codigo   on e.produto = p.codigo   */   join filiais f   /*  JOIN (filiaisgruposfiliais fgf  join gruposfiliais gf  on fgf.grupo = gf.codigo)  on f.codigo = fgf.filial  */   on e.filial = f.codigo   left join fatoresprecosfiliais fpf  on fpf.fatorpreco = c.fatorpreco   join colunasprecos cpn /* preço normal */  on cpn.caracteristica = p.caracteristica  AND cpn.preco = p.preco  AND cpn.coluna = f.preconormal   left join colunasprecos cpp /* preço promoção */  on cpp.caracteristica = p.caracteristica  AND cpp.preco = p.preco  AND cpp.coluna = f.precopromocao  and cpp.validade >= current_date   where e.produto in (348056, 329004, 329005, 329002, 192019, 192010, 348060, 348064, 348065, 348066, 2013, 401029, 319144, 319143, 860574, 860441, 860440, 999016, 860198500, 130207, 165011, 860622900, 860623100, 30349, 860340400, 330000, 330045, 319139, 192024, 401033, 130237, 130204, 130200, 432045, 860431, 429017, 166137, 432055, 432056, 183521, 183468, 183531, 183467, 183469, 183470, 1693, 1696, 130246, 192004, 44503