/* qryDetalhesCompra */  SELECT  e.produto,  e.datacompra,  e.precoCOMicms,  e.precoSEMicms,  e.qtdecompra,  e.aliquotaipi,  e.valorultimacompra,  e.filial,  p.datacadastro,   cast(  coalesce(  (  select sum(e1.financeiro) /  sum(e1.emestoque +  e1.reservado +  e1.reservaprevia +  e1.transito +  e1.demonstracao +  e1.conserto +  e1.danificada)   from estoques e1  where e1.produto = e.produto  and (e1.emestoque+e1.reservado+e1.reservaprevia+e1.transito+e1.demonstracao+e1.conserto+e1.danificada) <> 0  and e1.financeiro<>0  and e1.filial in ('1')  ),0.00) as numeric(11,2)) as customedio,    cast(case when ((e.emestoque+e.reservado+e.reservaprevia+e.transito+e.demonstracao+e.conserto+e.danificada) = 0) or  (coalesce(e.financeiro,0)=0) or  (coalesce(cpn.valor,0)=0) then 0  else ROUND( (cpn.valor / ( e.financeiro / (e.emestoque+e.reservado+e.reservaprevia+e.transito+e.demonstracao+e.conserto+e.danificada)) - 1) * 100,2)  end as numeric(15,2)) AS markup,    (SELECT pr.descricao FROM precos pr WHERE pr.caracteristica = p.caracteristica AND pr.codigo = p.preco) AS descricaopreco   FROM estoques e join produtos p on e.produto = p.codigo   /*  join (produtos p left join promocoes pro on p.promocao = pro.codigo)  join caracteristicas c  join marcas m  on c.marca = m.codigo   join grupos g  on c.grupo = g.codigo   join classes cl  on c.classe = cl.codigo   on p.caracteristica = c.codigo   on e.produto = p.codigo  */   join filiais f  on e.filial = f.codigo   join colunasprecos cpn /* preço normal */  on cpn.caracteristica = p.caracteristica  AND cpn.preco = p.preco  AND cpn.coluna = f.preconormal  where e.produto in (348056, 329004, 329005, 329002, 192019, 192010, 348060, 348064, 348065, 348066, 2013, 401029, 319144, 319143, 860574, 860441, 860440, 999016, 860198500, 130207, 165011, 860622900, 860623100, 30349, 860340400, 330000, 330045, 319139, 192024, 401033, 130237, 130204, 130200, 432045, 860431, 429017, 166137, 432055, 432056, 183521, 183468, 183531, 183467, 183469, 183470,