select selecao.* from ( SELECT pp.pedido,  pp.produto,  pp.quantidade,  p.entrega,  p.filialentrega,  pedidos_estoquepedido(pp.produto,p.filialentrega,pp.pedido) as quantidadependente,  p.emissao  FROM produtospedidos pp  join pedidos p  ON pp.pedido = p.numero and p.situacao in ('A', 'P')  where pp.produto in (348056, 329004, 329005, 329002, 192019, 192010, 348060, 348064, 348065, 348066, 2013, 401029, 319144, 319143, 860574, 860441, 860440, 999016, 860198500, 130207, 165011, 860622900, 860623100, 30349, 860340400, 330000, 330045, 319139, 192024, 401033, 130237, 130204, 130200, 432045, 860431, 429017, 166137, 432055, 432056, 183521, 183468, 183531, 183467, 183469, 183470, 1693, 1696, 130246, 192004, 445039, 192018, 192013, 192007, 192015, 192012, 192017, 183326, 183329, 183327, 183328, 444003, 444004, 444001, 444002, 444005, 444007, 444000, 444006, 192001, 183333, 183331, 183332, 860334300, 183335, 183334, 445015, 264019, 264020, 445041, 445043, 445042, 166122, 445064, 445063, 409010, 417117, 409011, 320117, 320279, 164187, 432059, 432060, 417182, 183236, 183435, 165378, 680116, 183201, 164001, 860549500, 188082, 860334200, 165264, 183119, 183504, 165132, 164162, 164091, 164107, 452002, 165010, 165543, 165542, 165265, 452005, 30350, 165720, 166077, 210155, 166084, 165320, 452004, 330046, 401019, 182009, 730053, 730051, 730000, 730240, 730242, 30372, 165583, 165585, 165624, 165589, 165584, 30316, 30191, 30194, 432048, 432049, 165739, 165541, 165740, 240103, 2710005, 330042, 183184, 183186, 183187, 860176, 165736, 330027, 860488300, 182015, 182006, 860340300, 165744, 165741, 165745, 700036, 860622800, 700063, 860623200, 860334100, 187096, 187097, 187098, 187074, 187078, 187094, 680155)  ) as selecao where selecao.quantidadependente >0 order by entrega, emissao, produto ;
 /* qryTotalProdutosSimilares */  ;  select cast('TOTAL' as varchar(5)) as total,  produtosml,  sum(quantidadesimilares) as quantidadesimilares,  sum(total_estoque) as total_estoque,  sum(emEstoque) as emEstoque,   sum(total_transito) as total_transito,  sum(reservado) as reservado,  sum(reservaprevia) as reservaprevia,   sum(futuro) as futuro,   sum(total_pedido) as total_pedido,  sum(total_pedidos_fornecedores) as total_pedidos_fornecedores,  sum(total_pedidos_filiais) as total_pedidos_filiais,    sum(total_vendido) as total_vendido,  sum(sugestao) as sugestao,   sum(minimo) as minimo,  sum(sugestaominimo) as sugestaominimo,  sum(maximo) as maximo,  sum(sugestaomaximo) as sugestaomaximo,   cast(  case when sum(total_vendido_temp)<>0 and '180' <> 0 then   (sum(emEstoque)/  (sum(Total_vendido_temp) / '180'))   else  cast(999999.99 as numeric(11,2))  end as numeric(12,2)) as diasestoque,   cast(  case when sum(total_vendido_temp)<>0 and '180' <> 0 then   ((sum(total_estoque) + sum(case when /*NULL*/ false then 0 else total_pedido end))/  (sum(Total_vendido_temp) / '180'))   else  cast(999999.99 as numeric(11,2))  end as numeric(12,2)) as diasestoquecompedidosdecompra    from  (  select produtosml,  sum(quantidadesimilares) as quantidadesimilares,  sum(total_estoque) as total_estoque,  sum(emestoque) as emestoque,   sum(total_transito) as total_transito,  sum(reservado) as reservado,  sum(reservaprevia) as reservaprevia,  sum(futuro) as futuro,  sum(total_pedido) as total_pedido,  sum(total_pedidos_fornecedores) as total_pedidos_fornecedores,  sum(total_pedidos_filiais) as total_pedidos_filiais,  sum(total_vendido) as total_vendido,  sum(sugestao) as sugestao,   cast(  case when sum(total_vendido)<>0 and periodo <> 0 then  sum(Total_vendido*'180'/periodo)  else  cast(null as numeric(11,2))  end as numeric) as total_vendido_temp,   /* sum(diasestoque) as diasestoque, */   sum(minimo) as minimo,  sum(sugestaominimo) as sugestaominimo,  sum(maximo) as maximo,  sum(sugestaomaximo) as sugestaomaximo  from  (                   /* qryProdutosSimilares */   select  (cast(ROUND( ( cast((total_vendido) as float) / periodo) * sugestaopara ) as float) - total_estoque - total_pedido + futuro) as sugestao,  selecionados7.*   from  (   select selecionados6.*,  /*  case when selecionados6.diasestoque_geral > '60' then  '60'  else  */  coalesce((select rcc.sugestaopara  from reducaoconsultacompras rcc  where rcc.estoquepara <= selecionados6.diasestoque_geral  and 'f'  and (select max(rcc2.estoquepara) from reducaoconsultacompras rcc2) >= selecionados6.diasestoque_geral  order by rcc.estoquepara  desc limit 1),'60')  /* end */ as sugestaopara  from  (   select selecionados5.*,    cast(  case when coalesce(total_vendido,0)<>0 then  (emestoque / (total_vendido / periodo ))  else  cast(999999.99 as numeric(11,2))  end as numeric(12,2)) as diasestoque,   cast(  case when coalesce(total_vendido,0)<>0 then  ((total_estoque + case when /*NULL*/ false then 0 else total_pedido end - futuro)/  (total_vendido / periodo ))  else  cast(999999.99 as numeric(11,2))  end as numeric(12,2)) as diasestoquecompedidosdecompra,   case when 'f' /*and not 'f'*/ then    cast(  case when coalesce(vendido_filiais,0)<>0 then  ((estoque_filiais + total_pedido_filiais)/  (vendido_filiais / Periodo))  else  cast(null as numeric(11,2))  end as numeric(12,2))   else   cast(  case when coalesce(total_vendido,0)<>0 then  (emestoque / (total_vendido / periodo ))  else  cast(999999.99 as numeric(11,2))  end as numeric(12,2))  end as diasestoque_geral      from  (  SELECT *,  /*SE TEM SUGESTAO DE COMPRA, DE ACORDO COM DIASESTOQUE, ENTAO RECALCULA A SUGESTAO DE ACORDO COM DIAS PROPORCIONAL*/  case when sugestao1 <= 0 then 0 else (cast(ROUND( ( cast((total_vendido) as float) / periodo) * '60' ) as float) - total_estoque - total_pedido + futuro) end as sugestao2  from  (  SELECT *, (cast(ROUND( ( cast((total_vendido) as float) / periodo) * '60' ) as float) - total_estoque - total_pedido + futuro) AS sugestao1  FROM  (  SELECT selecionados2.*,  colunasprecos.valor AS precovenda,  cast(case when selecionados2.customedio = 0 then 0  else ROUND( (colunasprecos.valor / selecionados2.customedio - 1) * 100,2)  end as numeric(15,2)) AS markup,   case when selecionados2.datacadastro between '22/01/2026' and '21/07/2026' then  case when '21/07/2026' = selecionados2.datacadastro then 1  else '21/07/2026' - selecionados2.datacadastro end  else '180' end as periodo   FROM  (  select selecionados1.*,  estoques.precoCOMicms, estoques.precoSEMicms, estoques.aliquotaIPI,  estoques.qtdecompra,  estoques.datacompra,  cast(case when (quantidadetotaldoestoque(estoques.produto,estoques.filial)) = 0 then 0  else ROUND( estoques.financeiro /  (quantidadetotaldoestoque(estoques.produto,estoques.filial)),2)  end as numeric(11,2)) AS customedio  FROM   (                                 select p.*,  cast(case when (p.minimo - p.saldo)<0 then 0 else (p.minimo-p.saldo) end as float) as sugestaominimo,  cast(case when (p.maximo - p.saldo)<0 then 0 else (p.maximo-p.saldo) end as float) as sugestaomaximo    from  (  select p.*,  ( p.total_pedidos_fornecedores + p.total_pedidos_filiais) AS total_pedido,   p.total_estoque + p.total_pedidos_fornecedores - p.futuro as saldo   from  (   select p.linha,  p.coluna,  p.codigogrupo,  p.grupo,  p.codigomarca,  p.marca,  p.codigoclasse,  p.classe,  p.promocao,  p.descricaopromocao,  p.produto,  p.produtovisual,  p.produtosml,  p.nomeproduto,  p.valorgrade1,  p.valorgrade2,  p.csosn,  p.incidencia,  p.composto,  p.caracteristica,  p.caracteristicavisual,  p.referencia,  p.resultadocurvaabc,  p.lembrarpedido,   p.obslembrarpedido,   p.datacadastro,  p.preco,    coalesce((select e2.filial  from estoques e2  where e2.produto = p.produto and  e2.datacompra = max(e.datacompra)  limit 1), 1) as filial,    sum(0 + e.emEstoque + e.Reservado + e.Transito + e.Demonstracao + e.Conserto + e.Danificada + e.reservaprevia) as total_estoque,    SUM ( e.emestoque ) AS emEstoque,  SUM ( e.transito ) AS total_transito,   /* SUM ( estoquesprodutos.pedido + estoquesprodutos.pedidos_filiais) AS total_pedido,*/   /* SUM ( estoquesprodutos.pedido) AS total_pedidos_fornecedores, pedidos_estoquepedido_filial */ /* SUM ( estoquesprodutos.pedidos_filiais) as total_pedidos_filiais, pedidos_filial */ /* SUM ( estoquesprodutos.vendido ) AS total_vendido, vendido_filial */    CAST (SUM (e.reservado) as float) as reservado,  CAST (SUM (e.reservaprevia) as float) as reservaprevia,  CAST (SUM (e.futuro) as float) as futuro,  cast(SUM(e.minimo) as float) as minimo,   cast (SUM (maximo) as float) as maximo,     case when not 'f' then sum(p.vendido_filiais)   else   coalesce(sum((SELECT sum(quantidade)  from json_to_recordset(movimentos_vendido_json) as (filial integer, quantidade numeric(11,3))  where json_to_recordset.filial = e.filial  )),0)+  coalesce(sum((SELECT sum(quantidade)  from json_to_recordset(cast(faturadosnaoentregues_ as json)) as (filial integer, quantidade numeric(11,3))  where json_to_recordset.filial = e.filial  )),0)  end as total_vendido, /* vendido */    /*  case when not 'f' then sum(p.pedidos_filiais)  else  */  coalesce(sum((SELECT sum(quantidade)  from json_to_recordset(pedidos_filiais_json) as  (requisitante integer, quantidade numeric(11,3))  where json_to_recordset.requisitante = e.filial  )),0)  /*end */ as total_pedidos_filiais, /* pedidos_filiais */   case when not 'f' then sum(p.pedidos_estoquepedido_filiais)  else  coalesce(sum((SELECT sum(quantidade)  from json_to_recordset(pedidos_estoquepedido_json) as (filialentrega integer, quantidade numeric(11,3))  where json_to_recordset.filialentrega = e.filial)),0)  end as total_pedidos_fornecedores, /* pedidos_estoquepedido */   sum(p.vendido_filiais) as vendido_filiais,  sum(p.pedidos_filiais) as pedidos_filiais,  sum(p.pedidos_estoquepedido_filiais) as pedidos_estoquepedido_filiais,  sum(( p.pedidos_estoquepedido_filiais + p.pedidos_filiais)) AS total_pedido_filiais,  sum(p.estoque_filiais) as estoque_filiais,   count(*) as quantidadesimilares     from estoques e,      (        select p.*,  coalesce((SELECT sum(quantidade)  from json_to_recordset(movimentos_vendido_json) as (quantidade numeric(11,3))),0)+  coalesce((SELECT sum(quantidade)  from json_to_recordset(faturadosnaoentregues_ ) as (quantidade numeric(11,3))),0)   as vendido_filiais,   coalesce((SELECT sum(quantidade)  from json_to_recordset(pedidos_estoquepedido_json) as (quantidade numeric(11,3))),0)  as pedidos_estoquepedido_filiais,   coalesce((SELECT sum(quantidade)  from json_to_recordset(pedidos_filiais_json) as (situacao char(1), quantidade numeric(11,3))  where json_to_recordset.situacao = 'A'  ),0)  as pedidos_filiais        from  (         select p.*,   movimentos_vendido_json('22/01/2026', '21/07/2026', p.produto, p.listafiliais, ''/*''*/),    ( select json_agg(sel.jsonr) from   (SELECT json_build_object('filial', filial, 'quantidade', quantidade) as jsonr  from json_to_recordset(cast(faturadosnaoentregues as json)) as (filial integer, quantidade numeric(11,3))  where json_to_recordset.filial in (select * from lista_int(cast('{'||p.listafiliais||'}' as integer[])))  ) as sel) as faturadosnaoentregues_,         case when 'f' then cast(null as json) else  (select jsonr from pedidos_estoquepedido_json (p.produto, p.listafiliais))  end as pedidos_estoquepedido_json,    case when not 't' then cast(null as json) ELSE   ( select json_agg(sel.jsonr) from (   select json_build_object('requisitante', pf.requisitante,  'quantidade', sum((case when pf.situacao='A' then pf.qtdepedida else pf.qtderecebida end)),  'situacao', pf.situacao) as jsonr  from pedidosfiliais pf  where pf.produto = p.produto  and pf.requisitante in (select * from lista_int(cast('{'||p.listafiliais||'}' as integer[])))  and pf.situacao in ('A','F')  group by pf.requisitante, pf.situacao) as sel  )   end as pedidos_filiais_json        FROM  (          select p.*,  cast(e.filial as varchar) as ListaFiliais, /* cast(e.filial as varchar) as ListaFiliais, */  sum(0 + e.emEstoque + e.Reservado + e.Transito + e.Demonstracao + e.Conserto + e.Danificada + e.reservaprevia) as estoque_filiais /* sum(0 + e.emEstoque + e.Transito) as estoque_filiais */  from  estoques e,    (      select p.*,   cast(faturadosnaoentregues.jsonr as varchar(1000)) as faturadosnaoentregues  from  (  select gr1.descricao as linha,  gr2.descricao as coluna,  c.grupo as codigogrupo,  g.descricao as grupo,   c.classe as codigoclasse,  cl.descricao as classe,  p.promocao,  pro.descricao as descricaopromocao,   c.marca as codigomarca,  m.descricao as marca,  p.codigo as produto,  p.codigovisual as produtovisual,  p.descricao as nomeproduto,  p.valorgrade1,  p.valorgrade2,  c.composto,  p.caracteristica,  c.codigovisual as caracteristicavisual,  p.referencia,  p.preco,  p.resultadocurvaabc,  p.lembrarpedido, p.obslembrarpedido,  p.datacadastro,  p.inativo,   (select ti.valor from tributosicms ti where ti.codigo = c.incidencia) as incidencia,  c.csosn,  similares.produtosml    from ((((((caracteristicas c join classes cl on c.classe = cl.codigo)  join marcas m on c.marca = m.codigo)  join grupos g on c.grupo = g.codigo)   join (produtos p left join promocoes pro on p.promocao = pro.codigo)  on p.caracteristica = c.codigo)  left join grades gr1 on gr1.codigo = c.grade1)  left join grades gr2 on gr2.codigo = c.grade2),          (    SELECT distinct codigo, produto as produtosml   from  (   (   select distinct ps.codigo, psel_similar.psel_codigo as produto    from (produtos ps  join caracteristicas cs  on ps.caracteristica = cs.codigo),   (   select distinct  psel.codigo as psel_codigo,  psel.caracteristica as psel_caracteristica,  psel.agrupamentosimilares as psel_agrupamentosimilares,  psel.grade1 as psel_grade1,  psel.grade2 as psel_grade2,  psel.valorgrade1 as psel_valorgrade1,  psel.valorgrade2 as psel_valorgrade2,  s."similar"    from similares s right outer join    (  select p.codigo,   p.caracteristica,   c.agrupamentosimilares,  c.grade1,  c.grade2,  p.valorgrade1,  p.valorgrade2    from produtos p   join caracteristicas c  on p.caracteristica = c.codigo  where p.codigo in (348056, 329004, 329005, 329002, 192019, 192010, 348060, 348064, 348065, 348066, 2013, 401029, 319144, 319143, 860574, 860441, 860440, 999016, 860198500, 130207, 165011, 860622900, 860623100, 30349, 860340400, 330000, 330045, 319139, 192024, 401033, 130237, 130204, 130200, 432045, 860431, 429017, 166137, 432055, 432056, 183521, 183468, 183531, 183467, 183469, 183470, 1693, 1696, 130246, 192004, 445039, 192018, 192013, 192007, 192015, 192012, 192017, 183326, 183329, 183327, 183328, 444003, 444004, 444001, 444002, 444005, 444007, 444000, 444006, 192001, 183333, 183331, 183332, 860334300, 183335, 183334, 445015, 264019, 264020, 445041, 445043, 445042, 166122, 445064, 445063, 409010, 417117, 409011, 320117, 320279, 164187, 432059, 432060, 417182, 183236, 183435, 165378, 680116, 183201, 164001, 860549500, 188082, 860334200, 165264, 183119, 183504, 165132, 164162, 164091, 164107, 452002, 165010, 165543, 165542, 165265, 452005, 30350, 165720, 166077, 210155, 166084, 165320, 452004, 330046, 401019, 182009, 730053, 730051, 730000, 730240, 730242, 30372, 165583, 165585, 165624, 165589, 165584, 30316, 30191, 30194, 432048, 432049, 165739, 165541, 165740, 240103, 2710005, 330042, 183184, 183186, 183187, 860176, 165736, 330027, 860488300, 182015, 182006, 860340300, 165744, 165741, 165745, 700036, 860622800, 700063, 860623200, 860334100, 187096, 187097, 187098, 187074, 187078, 187094, 680155)  ) as psel    ON s.caracteristica = psel.caracteristica   ) as psel_similar    where (ps.caracteristica = psel_similar.similar or   ps.caracteristica = psel_similar.psel_caracteristica)    /* and ps.codigo <> psel_similar.psel_codigo*/   /*  and ((ps.inativo IS NULL) OR  (ps.inativo>CURRENT_DATE))  */    and case when coalesce(psel_agrupamentosimilares, '') = 'L'  AND psel_grade1 IS NOT NULL  AND psel_valorgrade1 IS NOT NULL then     ps.valorgrade1 = psel_valorgrade1  and cs.grade1 = psel_grade1      when coalesce(psel_agrupamentosimilares, '') = 'C'  AND psel_grade2 IS NOT NULL  AND psel_valorgrade2 IS NOT NULL then     ps.valorgrade2 = psel_valorgrade2  and cs.grade2 = psel_grade2    else true end     )   union all    (  SELECT ps."similar" as codigo, ps.produto  FROM produtos_similares ps  WHERE ps.produto in (348056, 329004, 329005, 329002, 192019, 192010, 348060, 348064, 348065, 348066, 2013, 401029, 319144, 319143, 860574, 860441, 860440, 999016, 860198500, 130207, 165011, 860622900, 860623100, 30349, 860340400, 330000, 330045, 319139, 192024, 401033, 130237, 130204, 130200, 432045, 860431, 429017, 166137, 432055, 432056, 183521, 183468, 183531, 183467, 183469, 183470, 1693, 1696, 130246, 192004, 445039, 192018, 192013, 192007, 192015, 192012, 192017, 183326, 183329, 183327, 183328, 444003, 444004, 444001, 444002, 444005, 444007, 444000, 444006, 192001, 183333, 183331, 183332, 860334300, 183335, 183334, 445015, 264019, 264020, 445041, 445043, 445042, 166122, 445064, 445063, 409010, 417117, 409011, 320117, 320279, 164187, 432059, 432060, 417182, 183236, 183435, 165378, 680116, 183201, 164001, 860549500, 188082, 860334200, 165264, 183119, 183504, 165132, 164162, 164091, 164107, 452002, 165010, 165543, 165542, 165265, 452005, 30350, 165720, 166077, 210155, 166084, 165320, 452004, 330046, 401019, 182009, 730053, 730051, 730000, 730240, 730242, 30372, 165583, 165585, 165624, 165589, 165584, 30316, 30191, 30194, 432048, 432049, 165739, 165541, 165740, 240103, 2710005, 330042, 183184, 183186, 183187, 860176, 165736, 330027, 860488300, 182015, 182006, 860340300, 165744, 165741, 165745, 700036, 860622800, 700063, 860623200, 860334100, 187096, 187097, 187098, 187074, 187078, 187094, 680155) /* = NULL */   )    ) as ps  order by codigo      ) as similares    where p.codigo = similares.codigo      order by p.codigo   ) as p      left join /* Questão de perforamance foi feito a consulta abaixo e não produto por produto como as demais */    (   select *   from ProdutosContratosFaturadosouParciaisNaoEntregues_setof('22/01/2026', '21/07/2026', '')  ) as faturadosnaoentregues  on p.produto = faturadosnaoentregues.produto    ) as p    where e.produto = p.produto   /*  Ficou sem sentido restringir a seleção da filial (filial da data de compra) na qual vai ser totalizada geral ao usar tabela redutora  */   /*  and case when not 'f' or ('f' and 'f') then  e.filial =      coalesce((select e2.filial  from estoques e2  where e2.produto = e.produto           order by e2.datacompra desc limit 1    ), 1)    else true end   */   and ( e.filial IN ('1'))          group by p.produto,   e.filial,  p.datacadastro,   p.linha,  p.coluna,  p.codigogrupo,  p.grupo,  p.codigomarca,  p.marca,  p.codigoclasse,  p.classe,  p.promocao,  p.descricaopromocao,  p.produto,  p.produtovisual,  p.nomeproduto,  p.valorgrade1,  p.valorgrade2,  p.composto,  p.caracteristica,  p.caracteristicavisual,  p.referencia,  p.preco,  p.resultadocurvaabc,  p.lembrarpedido,  p.obslembrarpedido,  p.datacadastro,  p.incidencia,  p.csosn,  p.faturadosnaoentregues,  p.inativo,  p.produtosml    /*  ) as produtos on e.produto = produtos.produto  where true   and ( e.filial IN ('1'))     */  ) as p   ) as p    ) as p   where p.produto = e.produto  and case when 'f' then  e.filial in ((select * from lista_int(cast('{'||p.ListaFiliais||'}' as integer[]))))  else  e.filial = cast(p.ListaFiliais as integer)  end    and ( e.filial IN ('1'))        group by    p.linha,  p.coluna,  p.codigogrupo,  p.grupo,  p.codigomarca,  p.marca,  p.codigoclasse,  p.classe,  p.promocao,  p.descricaopromocao,  p.produto,  p.produtosml,  p.produtovisual,  p.nomeproduto,  p.valorgrade1,  p.valorgrade2,  p.csosn,  p.incidencia,  p.composto,  p.caracteristica,  p.caracteristicavisual,  p.referencia,  p.resultadocurvaabc,  p.lembrarpedido,   p.obslembrarpedido,   p.datacadastro,  p.preco   ) as p   ) as p                                       ) AS selecionados1 join estoques on selecionados1.produto = estoques.produto and  selecionados1.filial = estoques.filial  ) as selecionados2, filiais, colunasprecos  where selecionados2.filial = filiais.codigo and  colunasprecos.caracteristica = selecionados2.caracteristica and  colunasprecos.preco = selecionados2.preco and  colunasprecos.coluna = filiais.preconormal  ) AS selecionados3          ) as selecionados4  ) as selecionados5   /* sugestao2 */      ) as selecionados6  ) as selecionados7                               ) AS selecionados5  group by produtosml, periodo  ) as selecionados6  group by produtosml     /*   NULL   */ ;
